import type { ReactNode } from 'react';

import { cookies } from 'next/headers';

import { Separator } from '@/components/ui/separator';
import { SidebarInset, SidebarProvider, SidebarTrigger } from '@/components/ui/sidebar';

/** The sidebar component writes this cookie on every toggle, so the next page opens the same way. */
const SIDEBAR_COOKIE_NAME = 'sidebar_state';

export type AppShellProps = {
  sidebar: ReactNode;
  breadcrumb: ReactNode;
  /** Right end of the header bar, e.g. a `LocaleSwitcher`. */
  actions?: ReactNode;
  children: ReactNode;
};

/** Frame of a signed-in zone: collapsible sidebar, header with breadcrumb, the page below. */
export async function AppShell({ sidebar, breadcrumb, actions, children }: AppShellProps) {
  const cookieStore = await cookies();
  const defaultOpen = cookieStore.get(SIDEBAR_COOKIE_NAME)?.value !== 'false';

  return (
    <SidebarProvider defaultOpen={defaultOpen}>
      {sidebar}
      <SidebarInset className="min-w-0 md:peer-data-[variant=inset]:m-4 md:peer-data-[variant=inset]:ml-0 md:peer-data-[variant=inset]:rounded-[1em] md:peer-data-[variant=inset]:shadow-sm md:peer-data-[variant=inset]:peer-data-[state=collapsed]:ml-0">
        <header className="flex shrink-0 items-center gap-2 rounded-t-xl border-b bg-primary px-4 py-2 text-primary-foreground">
          <SidebarTrigger className="-ml-1" />
          <Separator orientation="vertical" className="mr-2 data-[orientation=vertical]:h-8" />
          <div className="min-w-0 flex-1">{breadcrumb}</div>
          {actions}
        </header>
        <div className="w-full min-w-0 flex-1">{children}</div>
      </SidebarInset>
    </SidebarProvider>
  );
}

'use client';

import type { ReactNode } from 'react';

import { IconLogout, IconSelector } from '@tabler/icons-react';
import { useTranslations } from 'next-intl';

import { AppLink } from '@/components/app-link';
import { LogoutForm } from '@/components/logout-form';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from '@/components/ui/sidebar';
import { Spinner } from '@/components/ui/spinner';
import { UserAvatar } from '@/components/user-avatar';

export type AppSidebarUser = {
  displayName: string;
  /** Second line under the name: email, role, unit… */
  subtitle?: string | null;
  profileImageUrl?: string | null;
};

export type AppSidebarProps = {
  /** The brand at the top; links to `/`. */
  logo: ReactNode;
  homeLabel: string;
  user: AppSidebarUser;
  /** Extra items of the profile menu, between the name and "Log out". */
  menu?: ReactNode;
  logoutAction?: string;
  children: ReactNode;
};

/** Sidebar with the brand, the app's nav groups (`children`) and the profile menu at the bottom. */
export function AppSidebar({
  logo,
  homeLabel,
  user,
  menu,
  logoutAction,
  children,
}: AppSidebarProps) {
  const t = useTranslations('ui.sidebar');
  const { isMobile } = useSidebar();

  return (
    <Sidebar collapsible="icon" variant="inset">
      <SidebarHeader className="pt-4 group-data-[collapsible=icon]:hidden">
        <AppLink href="/" aria-label={homeLabel} className="flex h-10 items-center px-2">
          {logo}
        </AppLink>
      </SidebarHeader>
      <SidebarContent>{children}</SidebarContent>
      <SidebarFooter>
        <SidebarMenu>
          <SidebarMenuItem>
            <DropdownMenu>
              <DropdownMenuTrigger
                render={
                  <SidebarMenuButton
                    size="lg"
                    tooltip={user.displayName}
                    aria-label={t('profileMenu')}
                  />
                }
              >
                <UserAvatar
                  name={user.displayName}
                  imageUrl={user.profileImageUrl}
                  className="size-8"
                />
                <span className="grid min-w-0 flex-1 text-left text-sm leading-tight group-data-[collapsible=icon]:hidden">
                  <span className="truncate font-medium">{user.displayName}</span>
                  {user.subtitle && (
                    <span className="truncate text-xs text-sidebar-foreground/70">
                      {user.subtitle}
                    </span>
                  )}
                </span>
                <IconSelector className="ml-auto group-data-[collapsible=icon]:hidden" />
              </DropdownMenuTrigger>
              <DropdownMenuContent
                side={isMobile ? 'top' : 'right'}
                align="end"
                sideOffset={8}
                className="w-72 max-w-[calc(100vw-2rem)]"
              >
                <DropdownMenuGroup>
                  <DropdownMenuLabel>
                    <div className="grid min-w-0 gap-1">
                      <span
                        title={user.displayName}
                        className="truncate text-sm font-medium text-foreground"
                      >
                        {user.displayName}
                      </span>
                      {user.subtitle && (
                        <span title={user.subtitle} className="truncate text-xs font-normal">
                          {user.subtitle}
                        </span>
                      )}
                    </div>
                  </DropdownMenuLabel>
                </DropdownMenuGroup>
                {menu && (
                  <>
                    <DropdownMenuSeparator />
                    {menu}
                  </>
                )}
                <DropdownMenuSeparator />
                <LogoutForm action={logoutAction}>
                  {(pending) => (
                    <DropdownMenuItem
                      variant="destructive"
                      nativeButton
                      closeOnClick={false}
                      disabled={pending}
                      aria-busy={pending}
                      render={<button type="submit" className="w-full" />}
                    >
                      {pending ? <Spinner /> : <IconLogout />}
                      <span>{pending ? t('loggingOut') : t('logout')}</span>
                    </DropdownMenuItem>
                  )}
                </LogoutForm>
              </DropdownMenuContent>
            </DropdownMenu>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarFooter>
    </Sidebar>
  );
}

'use client';

import type { Icon } from '@tabler/icons-react';
import type { ReactNode } from 'react';

import { IconLock } from '@tabler/icons-react';
import { usePathname } from 'next/navigation';

import { AppLink } from '@/components/app-link';
import { useBaseHref } from '@/components/base-path-provider';
import {
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from '@/components/ui/sidebar';
import { cn } from '@/lib/utils';

export type AppSidebarNavItem = {
  href: string;
  label: string;
  icon: Icon;
  badge?: ReactNode;
  /** Shown but marked with a lock (feature off, no permission). */
  locked?: boolean;
};

export type AppSidebarNavProps = {
  label?: string;
  items: readonly AppSidebarNavItem[];
};

function isActive(pathname: string, href: string, home: string) {
  if (href === home) return pathname === home;
  return pathname === href || pathname.startsWith(`${href}/`);
}

/** One group of the sidebar menu; the current section is highlighted by pathname prefix. */
export function AppSidebarNav({ label, items }: AppSidebarNavProps) {
  const pathname = usePathname();
  const baseHref = useBaseHref();
  const { setOpenMobile } = useSidebar();

  return (
    <SidebarGroup>
      {label && <SidebarGroupLabel>{label}</SidebarGroupLabel>}
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map(({ href, label: itemLabel, icon: ItemIcon, badge, locked }) => (
            <SidebarMenuItem key={href}>
              <SidebarMenuButton
                isActive={isActive(pathname, baseHref(href), baseHref('/'))}
                tooltip={itemLabel}
                className={cn(
                  'font-medium text-primary hover:bg-sidebar-primary hover:text-sidebar-primary-foreground data-active:bg-sidebar-primary data-active:text-sidebar-primary-foreground',
                  locked && 'text-muted-foreground',
                )}
                render={<AppLink href={href} onClick={() => setOpenMobile(false)} />}
              >
                <ItemIcon />
                <span>{itemLabel}</span>
              </SidebarMenuButton>
              {locked ? (
                <SidebarMenuBadge className="text-muted-foreground">
                  <IconLock className="size-3.5" aria-hidden />
                </SidebarMenuBadge>
              ) : (
                badge
              )}
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

'use client';

import { type BreadcrumbRoute, buildBreadcrumbs } from '@athene-x/whimui/i18n';
import { usePathname } from 'next/navigation';
import { Fragment } from 'react';

import { AppLink } from '@/components/app-link';
import { stripBasePath, useBasePath } from '@/components/base-path-provider';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';

export type AppBreadcrumbProps<TLabel extends string> = {
  routes: readonly BreadcrumbRoute<TLabel>[];
  /** Turns a route label into text, e.g. `useTranslations('breadcrumbs')`; identity by default. */
  translate?: (label: TLabel) => string;
};

/** Crumbs for the current pathname (below the nearest `BasePathProvider`), from `routes` patterns. */
export function AppBreadcrumb<TLabel extends string>({
  routes,
  translate = (label) => label,
}: AppBreadcrumbProps<TLabel>) {
  const pathname = stripBasePath(useBasePath(), usePathname());
  const breadcrumbs = buildBreadcrumbs(routes, pathname);
  const parents = breadcrumbs.slice(0, -1);
  const current = breadcrumbs.at(-1);

  if (!current) return null;

  return (
    <Breadcrumb className="min-w-0">
      <BreadcrumbList className="flex-nowrap">
        {parents.map(({ href, label }) => (
          <Fragment key={href}>
            <BreadcrumbItem className="hidden md:inline-flex">
              <BreadcrumbLink
                render={
                  <AppLink
                    href={href}
                    className="text-primary-foreground hover:text-primary-foreground hover:underline"
                  />
                }
              >
                {translate(label)}
              </BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbSeparator className="hidden text-primary-foreground md:block" />
          </Fragment>
        ))}
        <BreadcrumbItem className="min-w-0">
          <BreadcrumbPage className="truncate font-medium text-primary-foreground">
            {translate(current.label)}
          </BreadcrumbPage>
        </BreadcrumbItem>
      </BreadcrumbList>
    </Breadcrumb>
  );
}
